/**
 * Test replace db name.
 *
 * @throws Exception
 *           the exception
 */
@Test
public void testReplaceDBName() throws Exception {
    HiveConf conf = new HiveConf(ColumnarSQLRewriter.class);
    conf.setBoolean(MetastoreConstants.METASTORE_ENABLE_CACHING, false);
    SessionState.start(conf);
    // Create test table
    createTable("default", "mytable", "testDB", "testTable_1");
    createTable("default", "mytable_2", "testDB", "testTable_2");
    createTable("default", "mytable_3", "testDB", "testTable_3");
    String query = "SELECT * FROM mydb.mytable t1 JOIN mydb.mytable_2 t2 ON t1.t2id = t2.id " + " left outer join mytable_3 t3 on t2.t3id = t3.id " + "WHERE A = 100";
    ColumnarSQLRewriter rewriter = new ColumnarSQLRewriter();
    rewriter.ast = HQLParser.parseHQL(query);
    rewriter.query = query;
    rewriter.analyzeInternal();
    String joinTreeBeforeRewrite = HQLParser.getString(rewriter.fromAST);
    System.out.println(joinTreeBeforeRewrite);
    // Rewrite
    CubeMetastoreClient client = CubeMetastoreClient.getInstance(conf);
    rewriter.replaceWithUnderlyingStorage(rewriter.fromAST, client);
    String joinTreeAfterRewrite = HQLParser.getString(rewriter.fromAST);
    System.out.println(joinTreeAfterRewrite);
    // Tests
    assertTrue(joinTreeBeforeRewrite.contains("mydb"));
    assertTrue(joinTreeBeforeRewrite.contains("mytable") && joinTreeBeforeRewrite.contains("mytable_2") && joinTreeBeforeRewrite.contains("mytable_3"));
    assertFalse(joinTreeAfterRewrite.contains("mydb"));
    assertFalse(joinTreeAfterRewrite.contains("mytable") && joinTreeAfterRewrite.contains("mytable_2") && joinTreeAfterRewrite.contains("mytable_3"));
    assertTrue(joinTreeAfterRewrite.contains("testdb"));
    assertTrue(joinTreeAfterRewrite.contains("testtable_1") && joinTreeAfterRewrite.contains("testtable_2") && joinTreeAfterRewrite.contains("testtable_3"));
    // Rewrite one more query where table and db name is not set
    createTable("default", "mytable_4", null, null);
    String query2 = "SELECT * FROM mydb.mytable_4 WHERE a = 100";
    rewriter = new ColumnarSQLRewriter();
    rewriter.ast = HQLParser.parseHQL(query2);
    rewriter.query = query2;
    rewriter.analyzeInternal();
    joinTreeBeforeRewrite = HQLParser.getString(rewriter.fromAST);
    System.out.println(joinTreeBeforeRewrite);
    // Rewrite
    rewriter.replaceWithUnderlyingStorage(rewriter.fromAST, client);
    joinTreeAfterRewrite = HQLParser.getString(rewriter.fromAST);
    System.out.println(joinTreeAfterRewrite);
    // Rewrite should not replace db and table name since its not set
    assertEquals(joinTreeAfterRewrite, joinTreeBeforeRewrite);
    // Test a query with default db
    Hive.get().dropTable("default", "mytable");
    createTable("default", "mytable", "default", null);
    String defaultQuery = "SELECT * FROM examples.mytable t1 WHERE A = 100";
    rewriter = new ColumnarSQLRewriter();
    rewriter.ast = HQLParser.parseHQL(defaultQuery);
    rewriter.query = defaultQuery;
    rewriter.analyzeInternal();
    joinTreeBeforeRewrite = HQLParser.getString(rewriter.fromAST);
    rewriter.replaceWithUnderlyingStorage(rewriter.fromAST, CubeMetastoreClient.getInstance(conf));
    joinTreeAfterRewrite = HQLParser.getString(rewriter.fromAST);
    assertTrue(joinTreeBeforeRewrite.contains("examples"), joinTreeBeforeRewrite);
    assertFalse(joinTreeAfterRewrite.contains("examples"), joinTreeAfterRewrite);
    System.out.println("default case: " + joinTreeAfterRewrite);
    Hive.get().dropTable("default", "mytable");
    Hive.get().dropTable("default", "mytable_2");
    Hive.get().dropTable("default", "mytable_3");
    Hive.get().dropTable("default", "mytable_4");
}

/**
 * Test get connection hsql.
 *
 * @throws Exception
 *           the exception
 */
@Test
public void testGetConnectionHSQL() throws Exception {
    final Configuration conf = new Configuration();
    conf.set(JDBCDriverConfConstants.JDBC_DRIVER_CLASS, "org.hsqldb.jdbc.JDBCDriver");
    conf.set(JDBCDriverConfConstants.JDBC_DB_URI, "jdbc:hsqldb:mem:mymemdb");
    conf.set(JDBCDriverConfConstants.JDBC_USER, "SA");
    conf.set(JDBCDriverConfConstants.JDBC_PASSWORD, "");
    final DataSourceConnectionProvider cp = new DataSourceConnectionProvider();
    int numThreads = 50;
    Thread[] threads = new Thread[numThreads];
    final AtomicInteger passed = new AtomicInteger(0);
    final Semaphore sem = new Semaphore(1);
    for (int i = 0; i < numThreads; i++) {
        final int thid = i;
        threads[thid] = new Thread(new Runnable() {

            @Override
            public void run() {
                Connection conn = null;
                Statement st = null;
                try {
                    conn = cp.getConnection(conf);
                    Assert.assertNotNull(conn);
                    // Make sure the connection is usable
                    st = conn.createStatement();
                    Assert.assertNotNull(st);
                    passed.incrementAndGet();
                } catch (SQLException e) {
                    LOG.error("error getting connection to db!", e);
                } finally {
                    if (st != null) {
                        try {
                            st.close();
                        } catch (SQLException e) {
                            e.printStackTrace();
                        }
                    }
                    if (conn != null) {
                        try {
                            conn.close();
                        } catch (SQLException e) {
                            e.printStackTrace();
                        }
                    }
                }
            }
        });
        threads[thid].start();
    }
    for (Thread t : threads) {
        t.join();
    }
    cp.close();
    Assert.assertEquals(passed.get(), numThreads);
}

/**
 * Test get connection timeout.
 *
 * @throws Exception
 *           the exception
 */
@Test
public void testGetConnectionTimeout() throws Exception {
    final Configuration conf = new Configuration();
    conf.set(JDBCDriverConfConstants.JDBC_DRIVER_CLASS, "org.hsqldb.jdbc.JDBCDriver");
    conf.set(JDBCDriverConfConstants.JDBC_DB_URI, "jdbc:hsqldb:mem:mymemdb2");
    conf.set(JDBCDriverConfConstants.JDBC_USER, "SA");
    conf.set(JDBCDriverConfConstants.JDBC_PASSWORD, "");
    // Set a low timeout
    conf.setInt(JDBCDriverConfConstants.JDBC_GET_CONNECTION_TIMEOUT, 1000);
    final int MAX_CONNECTIONS = 3;
    conf.setInt(JDBCDriverConfConstants.JDBC_POOL_MAX_SIZE, MAX_CONNECTIONS);
    final DataSourceConnectionProvider cp = new DataSourceConnectionProvider();
    Connection[] connections = new Connection[MAX_CONNECTIONS + 1];
    for (int i = 0; i < MAX_CONNECTIONS + 1; i++) {
        // Last call should throw sql exception
        try {
            connections[i] = cp.getConnection(conf);
            if (i == MAX_CONNECTIONS) {
                fail("Expected last get connection to fail because of timeout");
            }
        } catch (SQLException sqlEx) {
            if (i != MAX_CONNECTIONS) {
                LOG.error("Unexpected getConnection error", sqlEx);
            }
            assertEquals(i, MAX_CONNECTIONS, "Failed before last getConnection call: " + sqlEx.getMessage());
        }
    }
    for (Connection c : connections) {
        if (c != null) {
            c.close();
        }
    }
}

