/**
 * Test handle event.
 *
 * @throws Exception
 *           the exception
 */
@Test
public void testHandleEvent() throws Exception {
    QueryHandle query = new QueryHandle(UUID.randomUUID());
    String user = "user";
    long now = System.currentTimeMillis();
    QueryFailed failed = new QueryFailed(now, QueryStatus.Status.RUNNING, QueryStatus.Status.FAILED, query, user, null);
    QuerySuccess success = new QuerySuccess(now, QueryStatus.Status.RUNNING, QueryStatus.Status.SUCCESSFUL, query);
    QueuePositionChange positionChange = new QueuePositionChange(now, 1, 0, query);
    try {
        latch = new CountDownLatch(3);
        LOG.info("Sending event: " + failed);
        service.notifyEvent(failed);
        latch.await(5, TimeUnit.SECONDS);
        assertTrue(genericEventListener.processed);
        assertTrue(endedListener.processed);
        assertTrue(failedListener.processed);
        assertFalse(queuePositionChangeListener.processed);
        resetListeners();
        latch = new CountDownLatch(2);
        LOG.info("Sending event : " + success);
        service.notifyEvent(success);
        latch.await(5, TimeUnit.SECONDS);
        assertTrue(genericEventListener.processed);
        assertTrue(endedListener.processed);
        assertFalse(failedListener.processed);
        assertFalse(queuePositionChangeListener.processed);
        resetListeners();
        latch = new CountDownLatch(2);
        LOG.info("Sending event: " + positionChange);
        service.notifyEvent(positionChange);
        latch.await(5, TimeUnit.SECONDS);
        assertTrue(genericEventListener.processed);
        assertFalse(endedListener.processed);
        assertFalse(failedListener.processed);
        assertTrue(queuePositionChangeListener.processed);
        resetListeners();
        LensEvent genEvent = new LensEvent(now) {

            @Override
            public String getEventId() {
                return "TEST_EVENT";
            }
        };
        latch = new CountDownLatch(1);
        LOG.info("Sending generic event " + genEvent.getEventId());
        service.notifyEvent(genEvent);
        latch.await(5, TimeUnit.SECONDS);
        assertTrue(genericEventListener.processed);
        assertFalse(endedListener.processed);
        assertFalse(failedListener.processed);
        assertFalse(queuePositionChangeListener.processed);
    } catch (LensException e) {
        fail(e.getMessage());
    }
}

/**
 * Test lens server dao.
 *
 * @throws Exception
 *           the exception
 */
@Test
public void testLensServerDAO() throws Exception {
    QueryExecutionServiceImpl service = (QueryExecutionServiceImpl) LensServices.get().getService("query");
    // Test insert query
    QueryContext queryContext = service.createContext("SELECT ID FROM testTable", "foo@localhost", new LensConf(), new Configuration());
    long submissionTime = queryContext.getSubmissionTime();
    queryContext.setQueryName("daoTestQuery1");
    FinishedLensQuery finishedLensQuery = new FinishedLensQuery(queryContext);
    finishedLensQuery.setStatus(QueryStatus.Status.SUCCESSFUL.name());
    String finishedHandle = finishedLensQuery.getHandle();
    service.lensServerDao.insertFinishedQuery(finishedLensQuery);
    FinishedLensQuery actual = service.lensServerDao.getQuery(finishedHandle);
    Assert.assertEquals(actual.getHandle(), finishedHandle);
    // Test find finished queries
    LensSessionHandle session = service.openSession("foo@localhost", "bar", new HashMap<String, String>());
    List<QueryHandle> persistedHandles = service.lensServerDao.findFinishedQueries(null, null, null, submissionTime, System.currentTimeMillis());
    if (persistedHandles != null) {
        for (QueryHandle handle : persistedHandles) {
            LensQuery query = service.getQuery(session, handle);
            if (!handle.getHandleId().toString().equals(finishedHandle)) {
                Assert.assertTrue(query.getStatus().isFinished(), query.getQueryHandle() + " STATUS=" + query.getStatus().getStatus());
            }
        }
    }
    System.out.println("@@ State = " + queryContext.getStatus().getStatus().name());
    List<QueryHandle> daoTestQueryHandles = service.lensServerDao.findFinishedQueries(finishedLensQuery.getStatus(), queryContext.getSubmittedUser(), "daotestquery1", -1L, Long.MAX_VALUE);
    Assert.assertEquals(daoTestQueryHandles.size(), 1);
    Assert.assertEquals(daoTestQueryHandles.get(0).getHandleId().toString(), finishedHandle);
}

